alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.board_members
    where board_id = p_board_id
      and user_id = auth.uid()
  );
$$;

create or replace function public.is_board_editor(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.board_members
    where board_id = p_board_id
      and user_id = auth.uid()
      and role = 'editor'
  );
$$;

create or replace function public.is_board_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.boards
    where id = p_board_id
      and is_archived = true
  );
$$;

create or replace function public.can_edit_card(p_card_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.cards c
    join public.board_members m on m.board_id = c.board_id
    where c.id = p_card_id
      and m.user_id = auth.uid()
      and m.role = 'editor'
      and not exists (
        select 1
        from public.boards b
        where b.id = c.board_id
          and b.is_archived = true
      )
  );
$$;

create or replace function public.enforce_card_editor_target_board()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.board_id is distinct from old.board_id then
    if not public.is_board_editor(new.board_id) then
      raise exception 'can only move cards to boards where the user is an editor';
    end if;

    if public.is_board_archived(new.board_id) then
      raise exception 'cannot move card to archived board';
    end if;
  end if;

  return new;
end;
$$;

create trigger enforce_card_editor_target_board
before update on public.cards
for each row
execute function public.enforce_card_editor_target_board();

create policy "boards_select_members"
on public.boards
for select
to authenticated
using (public.is_board_member(id));

create policy "board_members_select_members"
on public.board_members
for select
to authenticated
using (public.is_board_member(board_id));

create policy "cards_select_members"
on public.cards
for select
to authenticated
using (public.is_board_member(board_id));

create policy "cards_insert_editors"
on public.cards
for insert
to authenticated
with check (
  public.is_board_editor(board_id)
  and not public.is_board_archived(board_id)
);

create policy "cards_update_editors"
on public.cards
for update
to authenticated
using (public.is_board_editor(board_id) and not public.is_board_archived(board_id))
with check (
  public.is_board_editor(board_id)
  and not public.is_board_archived(board_id)
);

create policy "cards_delete_editors"
on public.cards
for delete
to authenticated
using (public.is_board_editor(board_id) and not public.is_board_archived(board_id));

revoke all on public.boards from anon, authenticated;
revoke all on public.board_members from anon, authenticated;
revoke all on public.cards from anon, authenticated;

grant select on public.boards to authenticated;
grant select on public.board_members to authenticated;
grant select, insert, update, delete on public.cards to authenticated;

grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;

revoke all on sequence public.cards_id_seq from anon, authenticated;
grant usage, select on sequence public.cards_id_seq to authenticated;
grant all on sequence public.cards_id_seq to service_role;
