create schema private;

grant usage on schema private to anon, authenticated;

create function private.board_member(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.board_members m where m.board_id = p_board_id and m.user_id = auth.uid())
$$;

create function private.is_board_editor(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.board_members m where m.board_id = p_board_id and m.user_id = auth.uid() and m.role = 'editor')
$$;

create function private.board_open(p_board_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select not b.is_archived from public.boards b where b.id = p_board_id), false)
$$;

alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create policy boards_select on public.boards
  for select to authenticated
  using (private.board_member(id));

create policy board_members_select on public.board_members
  for select to authenticated
  using (private.board_member(board_id));

create policy cards_select on public.cards
  for select to authenticated
  using (private.board_member(board_id));

create policy cards_insert on public.cards
  for insert to authenticated
  with check (private.is_board_editor(board_id) and private.board_open(board_id));

create policy cards_update on public.cards
  for update to authenticated
  using (private.is_board_editor(board_id) and private.board_open(board_id))
  with check (private.is_board_editor(board_id) and private.board_open(board_id));

create policy cards_delete on public.cards
  for delete to authenticated
  using (private.is_board_editor(board_id) and private.board_open(board_id));
