alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create or replace function public.is_friend_of(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.friendships f
    where (f.requester_id = p_user_id and f.addressee_id = auth.uid())
       or (f.requester_id = auth.uid() and f.addressee_id = p_user_id)
       and f.status = 'accepted'
  );
$$;

revoke all on function public.is_friend_of(uuid) from public;
grant execute on function public.is_friend_of(uuid) to authenticated, service_role;

create or replace function public.posts_guard_author()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.author_id is distinct from old.author_id then
    raise exception 'posts.author_id cannot be changed';
  end if;
  return new;
end;
$$;

revoke all on function public.posts_guard_author() from public;

create trigger posts_guard_author
before update on public.posts
for each row
execute function public.posts_guard_author();

create policy posts_select
on public.posts
for select
to anon, authenticated
using (
  audience = 'public'
  or author_id = auth.uid()
  or (audience = 'friends' and public.is_friend_of(auth.uid()))
);

create policy posts_insert
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy posts_update
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy posts_delete
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy friendships_select
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy friendships_insert
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
);

create policy friendships_update
on public.friendships
for update
to authenticated
using (
  (requester_id = auth.uid() and status = 'pending')
  or (addressee_id = auth.uid() and status = 'pending')
)
with check (
  (requester_id = auth.uid() and status = 'pending')
  or (addressee_id = auth.uid() and status = 'accepted')
);

create policy friendships_delete
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

revoke all on public.friendships from anon;
revoke all on public.posts from anon;

grant select on public.posts to anon;
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
grant usage, select on sequence public.posts_id_seq to authenticated;
