create or replace function public.enforce_org_sso_requirement()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' or current_user = 'service_role' then
    return new;
  end if;

  if new.org_id is null then
    return new;
  end if;

  if not public.has_sso_session() then
    if exists (
      select 1 from public.orgs o
      where o.id = new.org_id
        and o.require_sso
    ) then
