    join public.units u on u.id = r.unit_id
    where r.id = p_request_id
      and public.is_building_staff(u.building_id)
  );
$$;

create or replace function public.prevent_request_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only status can be updated on requests';
  end if;

  if new.status not in ('open', 'in_progress', 'done') then
    raise exception 'Invalid request status';
  end if;

  if not public.can_update_request_status(old.id) then
    raise exception 'Only building staff can update request status';
  end if;

  return new;
end;
$$;

