create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_min_increment numeric;
  v_error text;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id
  for update;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  v_min_increment := v_auction.min_increment;
  v_current_highest := v_auction.highest_bid;

  if v_current_highest is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'Bid must be above the starting price';
    end if;
    v_current_highest := p_amount;
  else
    if p_amount <= v_current_highest + v_min_increment then
      raise exception 'Bid must be at least % above the current highest bid',
        v_current_highest + v_min_increment;
    end if;
    v_current_highest := p_amount;
  end if;

  update public.auctions
  set highest_bid = v_current_highest
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  return v_current_highest;
end;
$$;

