  on public.auctions
  for select
  to authenticated
  using (true);

-- R1: Bidders can see their own bids; sellers can see every bid on their auctions
create policy "authenticated can view own bids or seller's bids"
  on public.bids
  for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1 from public.auctions
      where id = auction_id and seller_id = auth.uid()
    )
  );

-- R2: Nobody can create, change or delete auctions or bids directly through the app
-- No insert/update/delete policies for authenticated role on either table

-- R5: Anonymous visitors cannot see or change anything
-- No policies for anon role

-- R6: Service role bypasses RLS by default, no policies needed

-- R3, R4: place_bid function with all validation rules
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
set search_path = public
as $$
declare
  v_auction public.auctions%rowtype;
  v_current_highest numeric(10, 2);
  v_uid uuid := auth.uid();
begin
  -- R4: Caller must be signed in
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  -- R4: Auction must exist
  select * into v_auction from public.auctions where id = p_auction_id;
  if not found then
    raise exception 'Auction not found';
  end if;

  -- R4: Auction must not have ended
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- R4: Caller cannot bid on their own auction
  if v_auction.seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  -- R4: Get current highest bid
  select highest_bid into v_current_highest from public.auctions where id = p_auction_id;

  -- R4: Validate amount
  if p_amount <= v_auction.starting_price then
    if v_current_highest is null then
      raise exception 'Bid must be above the starting price';
    else
      raise exception 'Bid must be above the starting price';
    end if;
  end if;

  if v_current_highest is not null then
    -- R4: Must be above highest bid plus minimum increment
    if p_amount <= v_current_highest + v_auction.min_increment then
      raise exception 'Bid must be at least % above the current highest bid',
        v_auction.min_increment;
    end if;
  end if;

  -- R3: Record the bid
  insert into public.bids (auction_id, bidder_id, amount)
  values (p_auction_id, v_uid, p_amount)
  returning id;

  -- R3: Update auction's highest bid
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_uid
  where id = p_auction_id;

  -- R3: Return the new highest bid
  return p_amount;
end;
$$;

